@prefix ex: <https://example.org/ontology/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .

ex:Employee a owl:Class .
ex:Department a owl:Class .
ex:belongsToDepartment a owl:ObjectProperty .

outputs.example:
@prefix ex: <https://example.org/ontology/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

ex:Employee a owl:Class .
ex:Department a owl:Class .
ex:belongsToDepartment a owl:ObjectProperty ;
  rdfs:domain ex:Employee ;
  rdfs:range ex:Department .

@prefix ex: <https://example.org/ontology/> .

ex:E-001 a ex:Employee ;
    ex:belongsToDepartment ex:D-01 .

ex:D-01 a ex:Department .

@prefix ex: <https://example.org/ontology/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

ex:EmployeeShape a sh:NodeShape ;
  sh:targetClass ex:Employee ;
  sh:property [
    sh:path ex:belongsToDepartment ;
    sh:class ex:Department
  ] .
# 本例不预设关系必填或唯一。
